import "fmt"

func swap(a, b **int) {
	*a, *b = *b, *a
}

func main() {
	x, y := 1, 2
	px, py := &x, &y
	swap(&px, &py)
	fmt.Println(*px)
	fmt.Println(*py)
	fmt.Println(x)
}

